/* @lc app=leetcode id=3504 lang=kotlin */ class Solution { fun pal(s: String): Array<BooleanArray> = Array(s.length) { BooleanArray(s.length) }.also { p -> (s.length - 1 downTo 0).forEach { i -> (i until s.length).forEach { j -> p[i][j] = s[i] == s[j] && (j - i < 2 || p[i + 1][j - 1]) } } } fun longestPalindrome(s: String, t: String): Int = pal(s).let { ps -> pal(t).let { pt -> s.indices.map { i -> (i until s.length).lastOrNull { ps[i][it] }?.let { it - i + 1 } ?: 0 }.let { palS -> t.indices.map { j -> (0..j).firstOrNull { pt[it][j] }?.let { j - it + 1 } ?: 0 }.let { palT -> Array(s.length) { IntArray(t.length) }.let { g -> maxOf(palS.max(), palT.max(), s.indices.maxOf { i -> t.indices.maxOf { j -> (if (s[i] == t[j]) 1 + (if (i > 0 && j < t.length - 1) g[i - 1][j + 1] else 0) else 0).also { g[i][j] = it }.let { v -> if (v == 0) 0 else 2 * v + maxOf(if (i + 1 < s.length) palS[i + 1] else 0, if (j >= 1) palT[j - 1] else 0) } } }) } } } } } }